// WF13 Public Discussion Connector Foundation config — VK PUBLIC groups/posts/comments (DEC-121).
// Source decision (Stage 3.4 matrix order: Avito -> Telegram -> VK): VK public discussions fill the
// audience_activity_signals gap (questions/objections/buying intent + author aggregates) that the two
// competitor-ad-heavy sources (Avito, Telegram) do not cover. Fixture-first, $0, NO external calls,
// no Claude, no auto-handoff to WF08. PUBLIC groups/posts/comments ONLY: no private chats/messages,
// no member extraction, no hidden contacts, no auto-outreach (CONTACT_AND_OUTREACH_POLICY).
function moscowIsoNow(){var m=new Date(Date.now()+10800000);return m.toISOString().replace('Z','+03:00');}
function moscowStamp(){var z=function(n){return String(n).padStart(2,'0');};var m=new Date(Date.now()+10800000);return m.getUTCFullYear()+z(m.getUTCMonth()+1)+z(m.getUTCDate())+'_'+z(m.getUTCHours())+z(m.getUTCMinutes())+z(m.getUTCSeconds());}
const now=moscowIsoNow();
const stamp=moscowStamp();
return [{ json: {
  fixture_mode:true,
  live_mode:false,
  // --- live v0.2 PLACEHOLDERS: live fetch is NOT implemented (no HTTP node in this workflow).
  // Enabling live requires explicit operator approval + transport decision (VK official API community/
  // wall methods with an n8n-bound token, or an Apify VK actor) + cost estimate. Guard fires regardless.
  live_transport:'none_not_implemented',
  live_group_allowlist:[],
  live_max_items_per_group:10,
  live_requires_operator_approval:true,
  platform:'vk',
  source_type_post:'social_post',
  source_type_comment:'social_comment',
  requested_by:'operator',
  request_type:'social_source_discovery',
  region:'Москва/МО',
  service_focus:'credit_broker',
  group_allowlist:[
    'kredity_msk_fixture',
    'biznes_finansy_fixture',
    'uslugi_msk_fixture'
  ],
  pipeline_limit:10,
  approval_status_for_unique:'new',
  write_duplicate_audit:true,
  hard_skip_debug_audit:false,
  duplicate_next_action:'monitor_duplicate',
  spreadsheet_id_placeholder:'PASTE_SPREADSHEET_ID',
  agent_request_id:'wf13_req_'+stamp,
  run_id:'wf13_'+stamp,
  created_at:now
}}];

// LIVE MODE GUARD — live VK fetch is NOT implemented in the WF13 foundation (DEC-121).
// This workflow contains NO HTTP node. Enabling live requires, in order: explicit operator approval,
// a chosen transport (VK official API community/wall/comments methods with an n8n-bound token, or an
// Apify VK actor), a bound credential, and a recorded cost estimate.
// PUBLIC groups/posts/comments only — no private chats/messages, no member extraction, no hidden
// contacts, no auto-outreach. The live_* config fields are PLACEHOLDERS; this guard fires regardless.
throw new Error('WF13 live_mode is not implemented in the foundation build. Fixture mode only (fixture_mode=true). Live VK public group/post/comment fetch requires explicit operator approval + transport + credential (see docs/N8N_WORKFLOW_13_PUBLIC_DISCUSSION_OR_REVIEWS_CONNECTOR_RU.md).');

// Normalize VK public posts/comments into the WF09/WF11-compatible record shape. Deterministic, $0.
// Audience focus (DEC-121): questions/objections from public discussions become question_objection
// records feeding WF08 -> WF10 audience_activity_signals. Contact policy (DEC-097/098/114): contact_public
// ONLY when visible verbatim in the public text; author profile_url ONLY when the profile is public;
// nothing reconstructed; no outreach — default manual_review.
function str(v){return v==null?'':String(v).trim();}
function low(v){return str(v).toLowerCase();}
function cut(s,n){s=str(s);return s.length>n?s.slice(0,n):s;}
function hashText(s){s=str(s);let h=5381;for(let i=0;i<s.length;i++){h=((h<<5)+h+s.charCodeAt(i))>>>0;}return ('00000000'+h.toString(16)).slice(-8);}
function canonUrl(u){u=str(u);return u.replace(/[?#].*$/,'').replace(/\/+$/,'');}
const cfg=$('Set Connector Config').first().json;
const items=$input.all().map(i=>i.json);
// niche vocabulary v0.1 hardcoded (credit_brokerage) — migrates to niche packs (DEC-100)
const STRONG=['кредитный брокер','ипотечный брокер','помощь в получении кредита','помощь с кредитом','кредит после отказов','после отказов','плохой кредитной историей','плохая кредитная история','кредит для бизнеса','оборотные','тендерные займ','банковские гарантии','рефинансирование','снижение ставки','одобрение кредита','подбор банка'];
const WEAK=['кредит','займ','банк','отказ','скоринг','ставк','заёмщик','ипотек','финанс','брокер','предоплат','просрочк'];
const HARD_NEG=['юридический адрес','регистрация ооо','регистрация ип','бухгалтер','эквайринг','pos-терминал','касса','печать и штамп','эцп','аренда офиса','коворкинг'];
const QUESTION=['подскажите','посоветуйте','кто брал','кто обращался','к кому обращаться','сколько это стоит','как получить','что делать','?'];
const OBJECTION=['мошенник','обман','кидал','предоплату и пропада','не верю','развод','боюсь'];
const KW=[['кредитный брокер','кредитный брокер'],['после отказов','после отказов'],['плох','плохая кредитная история'],['без предоплаты','без предоплаты'],['оплата за результат','оплата за результат'],['для бизнеса','бизнес-кредит'],['рефинансир','рефинансирование'],['просрочк','просрочки'],['предоплат','предоплата (доверие)'],['мошенник','недоверие к брокерам'],['отказ','отказы банков']];
const out=[];
for(const p of items){
  const isComment=(low(p.item_type)==='comment');
  const text=str(p.text);
  const blob=low(text)+' '+low(p.group_title);
  const valid=!!(str(p.group)&&str(p.item_id)&&text.length>=30);
  const strongHit=STRONG.filter(t=>blob.indexOf(t)>=0);
  const weakHit=WEAK.filter(t=>blob.indexOf(t)>=0);
  const negHit=HARD_NEG.filter(t=>blob.indexOf(t)>=0);
  const qHit=QUESTION.filter(t=>blob.indexOf(t)>=0);
  const objHit=OBJECTION.filter(t=>blob.indexOf(t)>=0);
  let record_type_hint='irrelevant';let touchpoint_type='irrelevant_source';let predicted_entity_type='irrelevant';let predicted_route='skipped_log';
  let lead_intent='none';let confidence=10;let hard_skip=false;let relevance_reason='';
  const looksAd=/тел[:.]|\+7|без предоплаты|оплата за результат|под ключ/i.test(text)&&!isComment;
  if(!valid){ relevance_reason='invalid: missing group/item_id or text<30'; }
  else if(negHit.length&&!strongHit.length){ hard_skip=true; relevance_reason='hard negative: '+negHit.join(', '); }
  else if(strongHit.length&&looksAd){ record_type_hint='competitor_activity';touchpoint_type='competitor_content_post';predicted_entity_type='competitor';predicted_route='monitor_queue';confidence=70;relevance_reason='strong competitor ad: '+strongHit.slice(0,4).join(', '); }
  else if((qHit.length||objHit.length)&&(strongHit.length||weakHit.length>=2)){ record_type_hint='question_objection';touchpoint_type='forum_discussion';predicted_entity_type='lead_signal';predicted_route='review_queue';lead_intent=objHit.length&&!qHit.length?'low':'medium';confidence=objHit.length&&!qHit.length?50:60;relevance_reason=(qHit.length?('question: '+qHit.slice(0,3).join(', ')):'')+(objHit.length?((qHit.length?'; ':'')+'objection: '+objHit.slice(0,3).join(', ')):''); }
  else if(strongHit.length){ record_type_hint='market_signal';predicted_entity_type='market_signal';touchpoint_type='forum_discussion';predicted_route='content_queue';confidence=50;relevance_reason='strong niche terms, no ad/question shape: '+strongHit.slice(0,4).join(', '); }
  else if(weakHit.length>=2){ record_type_hint='market_signal';predicted_entity_type='market_signal';touchpoint_type='forum_discussion';predicted_route='content_queue';confidence=45;relevance_reason='weak finance: '+weakHit.slice(0,4).join(', '); }
  else { hard_skip=true; relevance_reason='no niche evidence'; }
  // public contact: verbatim phone/@handle in the PUBLIC text only — never reconstructed (DEC-114 channel category).
  let contact='';let contactChannel='';let contactFormat='';
  const ph=text.match(/(?:\+7|8)[\s\-(]*\d{3}[\s\-)]*\d{3}[\s\-]*\d{2}[\s\-]*\d{2}/);
  const h=text.match(/@[a-zA-Z0-9_]{5,32}/);
  if(ph){contact=ph[0];contactChannel='phone';contactFormat='phone';}
  else if(h){contact=h[0];contactChannel='telegram';contactFormat='handle';}
  const kws=[];const seen={};for(const k of KW){if(blob.indexOf(k[0])>=0&&!seen[k[1]]){seen[k[1]]=1;kws.push(k[1]);}}
  let service='unknown';
  if(blob.indexOf('ипотек')>=0||blob.indexOf('рефинансир')>=0)service='mortgage_refinance';
  else if(blob.indexOf('для бизнеса')>=0||blob.indexOf('оборотные')>=0)service='business_credit';
  else if(blob.indexOf('после отказов')>=0||blob.indexOf('отказ')>=0)service='credit_after_refusals';
  if(blob.indexOf('кредитный брокер')>=0)service='credit_broker';
  const canon=canonUrl(p.item_url)+(isComment?('#reply'+str(p.comment_id)):'');
  const publicProfile=(p.author_profile_public===true);
  out.push({ json: {
    is_valid_listing:valid,
    hard_skip:hard_skip,
    relevance_reason:relevance_reason,
    source_type:isComment?(str(cfg.source_type_comment)||'social_comment'):(str(cfg.source_type_post)||'social_post'),
    platform:str(cfg.platform)||'vk',
    source_url:'https://vk.com/'+str(p.group),
    post_url:canon,
    profile_url:publicProfile?('https://vk.com/'+str(p.author_handle)):'',
    profile_name:str(p.author_name),
    author_handle:str(p.author_handle),
    author_key:str(p.author_handle)||str(p.author_name),
    published_at:str(p.published_at),
    region_hint:(blob.indexOf('москв')>=0||blob.indexOf(' мо')>=0?'Москва/МО':''),
    service_hint:service,
    query:'allowlist:'+str(p.group),
    text_context:isComment?('Обсуждение в публичной группе VK '+str(p.group_title)+', пост '+canonUrl(p.item_url)):cut(text,3500),
    comment_text:isComment?cut(text,3500):'',
    contact_public:contact,
    contact_channel:contactChannel,
    contact_format:contactFormat,
    dedup_key:'vk::'+(isComment?'social_comment':'social_post')+'::'+canon,
    text_hash:hashText(low(text)),
    record_type_hint:record_type_hint,
    touchpoint_type:touchpoint_type,
    lead_intent_hint:lead_intent,
    urgency_hint:'none',
    interest_topic:(record_type_hint==='competitor_activity')?'competitor VK ad copy':(record_type_hint==='question_objection'?'audience pain / question':(record_type_hint==='market_signal'?'market context':'')),
    probable_need:(record_type_hint==='question_objection'&&qHit.length)?'помощь с кредитом после отказов':'',
    competitor_related:(record_type_hint==='competitor_activity'),
    competitor_name:(record_type_hint==='competitor_activity')?str(p.author_name):'',
    semantic_keywords:kws.join(', '),
    ad_channel_hint:'vk',
    confidence_score:confidence,
    lead_temperature:(record_type_hint==='question_objection'&&lead_intent==='medium')?'warm':'none',
    next_action:(record_type_hint==='question_objection')?'investigate':'monitor',
    responsible:'operator',
    estimated_analysis_cost_usd:0,
    manager_note:'',
    predicted_route:predicted_route,
    predicted_entity_type:predicted_entity_type,
    contact_evidence_url:contact?canon:'',
    notes:''
  }});
}
return out;

// Dedup vs market_record_registry (dedup_key) + within batch. Mirrors WF09/WF11: invalid and
// hard-skipped items never register, never count unique, never consume the pipeline cap.
function str(v){return v==null?'':String(v).trim();}
const cfg=$('Set Connector Config').first().json;
const approvalUnique=str(cfg.approval_status_for_unique)||'new';
const dupNext=str(cfg.duplicate_next_action)||'monitor_duplicate';
const pipelineLimit=Number(cfg.pipeline_limit)||10;
const recs=$('Normalize VK Items').all().map(i=>i.json);
let reg=[];
try{reg=$('Read market_record_registry').all().map(i=>i.json).filter(Boolean);}catch(e){reg=[];}
const regSet=new Set(reg.map(r=>str(r&&r.dedup_key)).filter(Boolean));
const seen=new Set();
const out=[];
let acceptedCount=0;
for(const r of recs){
  if(r.is_valid_listing===false){ out.push({ json: Object.assign({}, r, { dedup_status:'invalid', approval_status:'invalid', next_action:'ignore' }) }); continue; }
  if(r.hard_skip===true){ out.push({ json: Object.assign({}, r, { dedup_status:'hard_skipped', approval_status:'skipped_irrelevant', next_action:'ignore' }) }); continue; }
  if(acceptedCount>=pipelineLimit){ out.push({ json: Object.assign({}, r, { dedup_status:'over_pipeline_limit', approval_status:'skipped', next_action:'ignore' }) }); continue; }
  acceptedCount++;
  const key=str(r.dedup_key);
  let dedup_status='unique';let approval_status=approvalUnique;let next_action=str(r.next_action);
  if(key&&regSet.has(key)){ dedup_status='duplicate_in_registry';approval_status='duplicate';next_action=dupNext; }
  else if(key&&seen.has(key)){ dedup_status='duplicate_in_batch';approval_status='duplicate';next_action=dupNext; }
  else { dedup_status='unique';if(key)seen.add(key); }
  out.push({ json: Object.assign({}, r, { dedup_status:dedup_status, approval_status:approval_status, next_action:next_action }) });
}
return out;

// Build raw_market_records rows (exactly 40 columns, matching WF07/WF09/WF11 schema). No external calls.
function str(v){return v==null?'':String(v).trim();}
function moscowIsoNow(){var m=new Date(Date.now()+10800000);return m.toISOString().replace('Z','+03:00');}
function moscowStamp(){var z=function(n){return String(n).padStart(2,'0');};var m=new Date(Date.now()+10800000);return m.getUTCFullYear()+z(m.getUTCMonth()+1)+z(m.getUTCDate())+'_'+z(m.getUTCHours())+z(m.getUTCMinutes())+z(m.getUTCSeconds());}
const cfg=$('Set Connector Config').first().json;
const reqId=str(cfg.agent_request_id);
const created=str(cfg.created_at);
const stamp=str(cfg.run_id).replace(/^wf13_/,'')||moscowStamp();
const writeDupAudit=(cfg.write_duplicate_audit===true||str(cfg.write_duplicate_audit).toLowerCase()==='true');
